-- Sukkar Plus — schema additions for the Python/FastAPI backend.
--
-- Builds on 20261028000001_schema.sql and 20261028000002_rls_and_rpc.sql.
-- Adds:
--   * sukkar_reports      — one row per uploaded PDF and its processing output
--   * notifications       — in-app notifications generated by real events
--   * appointment columns — specialty, status, source and the originating request
--   * followup_requests.appointment_id — the simulated appointment, once created
--   * patient_identities.health_record_number — fictional, for the ملفي card
--   * a private storage bucket for report files
--
-- Security model: patients read and write only their own rows (RLS on
-- auth.uid()); reviewers read nothing from patient tables directly. The
-- FastAPI backend holds the service-role key and performs the privileged
-- writes (processing output, simulated appointments, notifications) on the
-- user's behalf after checking the caller's role itself.

-- ---------------------------------------------------------------- columns

alter table public.patient_identities
  add column if not exists health_record_number text;

alter table public.appointments
  add column if not exists specialty_ar text not null default 'متابعة',
  add column if not exists status text not null default 'upcoming'
    check (status in ('upcoming', 'past', 'cancelled')),
  add column if not exists source text not null default 'prototype'
    check (source in ('prototype', 'demo_seed')),
  add column if not exists followup_id uuid,
  add column if not exists report_id uuid;

-- One simulated appointment per approved follow-up request.
create unique index if not exists appointments_one_per_followup
  on public.appointments (followup_id) where followup_id is not null;

alter table public.followup_requests
  add column if not exists appointment_id uuid references public.appointments (id) on delete set null;

-- ------------------------------------------------------- sukkar_reports

create table if not exists public.sukkar_reports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  status text not null default 'processing'
    check (status in ('processing', 'needs_review', 'ready', 'failed')),
  file_name text not null,
  file_size_bytes integer not null check (file_size_bytes >= 0),
  file_sha256 text,
  page_count integer not null default 0 check (page_count >= 0),
  -- private storage object key; null when file retention is switched off
  storage_path text,
  format_id text,
  format_verified boolean not null default false,
  device_label text,
  glucose_unit text not null default 'mg/dL' check (glucose_unit in ('mg/dL', 'mmol/L')),
  report_period jsonb,
  metrics_period jsonb,
  -- deterministic data-sufficiency summary; never raw report text
  data_quality jsonb,
  warnings jsonb not null default '[]',
  -- the full extraction result: every field with its printed label, page and checks
  extraction jsonb,
  -- the verified metric set the rules and summaries actually used
  verified_metrics jsonb not null default '[]',
  -- the rule evaluation: outcome, per-rule results, sources and limitations
  analysis jsonb,
  -- the Arabic summary and whether it came from the model or a local template
  ai_summary jsonb,
  error_ar text,
  provenance text not null default 'real' check (provenance in ('real', 'synthetic')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists sukkar_reports_user_idx
  on public.sukkar_reports (user_id, created_at desc);
create index if not exists sukkar_reports_status_idx
  on public.sukkar_reports (status) where status = 'processing';

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists sukkar_reports_touch on public.sukkar_reports;
create trigger sukkar_reports_touch
  before update on public.sukkar_reports
  for each row execute function public.touch_updated_at();

-- -------------------------------------------------------- notifications

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in (
    'report_ready', 'report_failed', 'followup_submitted',
    'followup_decided', 'appointment_created', 'general')),
  channel text not null default 'personal' check (channel in ('personal', 'general')),
  title text not null,
  body text not null,
  sender text not null default 'سكر بلس',
  link text,
  -- deterministic key per real event: reloading a page can never duplicate one
  dedupe_key text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create unique index if not exists notifications_dedupe
  on public.notifications (user_id, dedupe_key) where dedupe_key is not null;
create index if not exists notifications_user_idx
  on public.notifications (user_id, created_at desc);

-- ------------------------------------------------------------------ RLS

alter table public.sukkar_reports enable row level security;
alter table public.notifications enable row level security;

revoke all on public.sukkar_reports, public.notifications from anon, public;

drop policy if exists sukkar_reports_owner on public.sukkar_reports;
create policy sukkar_reports_owner on public.sukkar_reports
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());
grant select, insert, update, delete on public.sukkar_reports to authenticated;

drop policy if exists notifications_owner_select on public.notifications;
create policy notifications_owner_select on public.notifications
  for select to authenticated using (user_id = auth.uid());

-- Patients may mark their own notifications read and delete them, but never
-- create one: notifications come from real backend events only.
drop policy if exists notifications_owner_update on public.notifications;
create policy notifications_owner_update on public.notifications
  for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

drop policy if exists notifications_owner_delete on public.notifications;
create policy notifications_owner_delete on public.notifications
  for delete to authenticated using (user_id = auth.uid());

grant select, delete on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

-- ------------------------------------------------------- private storage

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('reports', 'reports', false, 15728640, array['application/pdf'])
on conflict (id) do update
  set public = false,
      file_size_limit = 15728640,
      allowed_mime_types = array['application/pdf'];

-- Objects live under "<user_id>/<report_id>.pdf"; a patient can only reach
-- their own folder, and only through a short-lived signed URL.
drop policy if exists reports_read_own on storage.objects;
create policy reports_read_own on storage.objects
  for select to authenticated
  using (bucket_id = 'reports' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists reports_delete_own on storage.objects;
create policy reports_delete_own on storage.objects
  for delete to authenticated
  using (bucket_id = 'reports' and (storage.foldername(name))[1] = auth.uid()::text);

-- ------------------------------------------------- retention / deletion

-- Extends delete_my_data() from the previous migration to the new tables.
create or replace function public.delete_my_data()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from public.notifications where user_id = uid;
  delete from public.sukkar_reports where user_id = uid;
  delete from public.followup_requests where user_id = uid;
  delete from public.visit_summaries where user_id = uid;
  delete from public.test_reminders where user_id = uid;
  delete from public.appointments where user_id = uid;
  delete from public.historical_comparisons where user_id = uid;
  delete from public.lab_results where user_id = uid;
  delete from public.device_reports where user_id = uid;
  delete from public.consents where user_id = uid;
  delete from public.patient_identities where user_id = uid;
end;
$$;

grant execute on function public.delete_my_data() to authenticated;

comment on table public.sukkar_reports is
  'Uploaded CGM report PDFs and the deterministic processing output. Report files themselves live in the private "reports" storage bucket when retention is enabled.';
comment on table public.notifications is
  'In-app notifications. Written by the backend only, from real events, with a deterministic dedupe_key.';
comment on column public.appointments.is_simulated is
  'Always true in this prototype. No real appointment is ever booked.';
